<?php $page_title='Stock Management'; require_once __DIR__.'/../includes/header.php'; require_perm($pdo,'stock','can_view'); $msg='';
$prods=$pdo->query("SELECT * FROM products ORDER BY name")->fetchAll(); $whs=$pdo->query("SELECT * FROM warehouses ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $pid=(int)$_POST['product_id']; $wid=(int)$_POST['warehouse_id']; $qty=(int)$_POST['quantity']; $type=clean($_POST['adjustment_type']??'add'); $notes=clean($_POST['notes']??'');
 try{ $pdo->beginTransaction(); $change=($type==='remove'?-$qty:$qty); adjust_stock($pdo,$pid,$wid,$change,'adjustment',gen_no('ADJ'),$notes); $pdo->commit(); $msg='Stock adjusted.'; audit_log($pdo,'Adjust Stock','stock',"Adjusted product $pid in warehouse $wid by $change"); }catch(Exception $e){ $pdo->rollBack(); $msg='Error: '.e($e->getMessage()); }
}
$rows=$pdo->query("SELECT s.*, p.name as pname, p.sku, w.name as wname, p.low_stock_threshold FROM stock s JOIN products p ON p.id=s.product_id JOIN warehouses w ON w.id=s.warehouse_id ORDER BY p.name")->fetchAll();
$moves=$pdo->query("SELECT m.*, p.name as pname, w.name as wname FROM stock_movements m JOIN products p ON p.id=m.product_id JOIN warehouses w ON w.id=m.warehouse_id ORDER BY m.id DESC LIMIT 30")->fetchAll();
?>
<?php if($msg): ?><div class="alert alert-info"><?= e($msg) ?></div><?php endif; ?>
<div class="row"><div class="col-md-4"><div class="card p-3"><h5>Adjust Stock</h5><form method="post"><?= csrf_field() ?><label class="form-label">Product</label><select name="product_id" class="form-select mb-2" required><?php foreach($prods as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?> (<?= e($p['sku']) ?>)</option><?php endforeach; ?></select><label class="form-label">Warehouse</label><select name="warehouse_id" class="form-select mb-2" required><?php foreach($whs as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><label class="form-label">Type</label><select name="adjustment_type" class="form-select mb-2"><option value="add">Add Stock</option><option value="remove">Remove Stock</option></select><label class="form-label">Quantity</label><input type="number" min="1" name="quantity" class="form-control mb-2" required><label class="form-label">Notes</label><input name="notes" class="form-control mb-2"><button class="btn btn-primary">Adjust</button></form></div></div>
<div class="col-md-8"><div class="card p-3"><h5>Current Stock</h5><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Warehouse</th><th>Qty</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['pname']) ?> (<?= e($r['sku']) ?>)</td><td><?= e($r['wname']) ?></td><td><?= (int)$r['quantity'] ?></td><td><?= $r['quantity']<=$r['low_stock_threshold']?'<span class="badge bg-danger">Low</span>':'<span class="badge bg-success">OK</span>' ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card p-3 mt-3"><h5>Recent Movements</h5><table class="table"><thead><tr><th>Type</th><th>Product</th><th>Warehouse</th><th>Qty</th><th>Date</th></tr></thead><tbody><?php foreach($moves as $m): ?><tr><td><?= e($m['movement_type']) ?></td><td><?= e($m['pname']) ?></td><td><?= e($m['wname']) ?></td><td><?= (int)$m['quantity'] ?></td><td><?= e($m['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
